-- SOURCE tables.sql sha256=8bd478dbdff50e9c1dfbd1e235712a618b3a4df1bb76a8d61b2b4c99e9f8cccb
-- Stage 1 only: degree programs, departments and institutional academic years.
-- Fail on an unexpected existing relation; historical migrations stay intact.
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;

CREATE TABLE public.departments (
    department_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 32
        AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'),
    description text CHECK (length(description) <= 2000),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (department_id, institution_id)
);
CREATE UNIQUE INDEX academic_foundation_department_code
    ON public.departments (institution_id, lower(btrim(code)));

CREATE TABLE public.programs (
    program_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    department_id uuid NOT NULL,
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 32
        AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'),
    description text CHECK (length(description) <= 2000),
    degree_type text NOT NULL CHECK (length(btrim(degree_type)) BETWEEN 1 AND 80),
    duration_years numeric NOT NULL CHECK (duration_years > 0 AND duration_years <= 20),
    total_credits numeric CHECK (total_credits > 0 AND total_credits <= 1000),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (department_id, institution_id)
        REFERENCES public.departments (department_id, institution_id) ON DELETE RESTRICT,
    UNIQUE (program_id, institution_id)
);
CREATE UNIQUE INDEX academic_foundation_program_code
    ON public.programs (institution_id, department_id, lower(btrim(code)));
CREATE INDEX academic_foundation_program_tenant ON public.programs (institution_id);

CREATE TABLE public.academic_years (
    academic_year_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 32
        AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'),
    start_date date NOT NULL CHECK (isfinite(start_date)),
    end_date date NOT NULL CHECK (isfinite(end_date)),
    is_current boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (end_date > start_date),
    CHECK (NOT is_current OR is_active),
    UNIQUE (academic_year_id, institution_id),
    EXCLUDE USING gist (
        institution_id WITH =, daterange(start_date, end_date, '[]') WITH &&
    ) WHERE (is_active)
);
CREATE UNIQUE INDEX academic_foundation_year_code
    ON public.academic_years (institution_id, lower(btrim(code)));
CREATE UNIQUE INDEX academic_foundation_current_year
    ON public.academic_years (institution_id) WHERE (is_current AND is_active);

COMMENT ON TABLE public.programs IS 'Degree programs, such as B.Tech CSE; these are not reusable subjects.';
COMMENT ON TABLE public.academic_years IS 'Institutional calendar years; program study-semester contexts are a later stage.';

-- SOURCE permissions.sql sha256=4f3dc06408ca24742e3b2eba83308dfeb0383311e7feb1791a0b07e3bc95e5a3
-- No staff delegation, academic wildcard permissions or unrelated role changes.
INSERT INTO public.permissions (code, name, description, scope, is_active)
SELECT resource || '.' || operation, title || ' ' || operation,
       'Academic Setup: ' || title || ' ' || operation, 'institution', true
FROM (VALUES ('departments', 'Departments'), ('programs', 'Degree programs'),
             ('academic_years', 'Academic years')) AS resources(resource, title)
CROSS JOIN (VALUES ('read'), ('manage')) AS operations(operation)
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    scope = EXCLUDED.scope, is_active = true, updated_at = now();

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.permission_id
FROM public.roles r CROSS JOIN public.permissions p
WHERE r.name = 'admin' AND p.code IN (
    'departments.read', 'departments.manage', 'programs.read', 'programs.manage',
    'academic_years.read', 'academic_years.manage'
)
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- SOURCE authorization.sql sha256=73f4d4b850703a1615040f73cb378989eb0f6ef2369228196eed94ca509226b9
-- Do not reuse retired academic helpers or aggregate permission provenance.
CREATE FUNCTION public.assert_academic_foundation_actor(
    p_actor_user_id uuid, p_institution_id uuid, p_resource text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Academic Setup requires the trusted backend' USING ERRCODE = '42501';
    END IF;
    -- Permission and authority must come from the SAME institution-scoped admin
    -- assignment. Platform/org roles and delegated user grants cannot satisfy it.
    PERFORM 1
    FROM public.users u
    JOIN public.user_roles ur ON ur.user_id = u.id
    JOIN public.roles r ON r.id = ur.role_id
    JOIN public.role_permissions rp ON rp.role_id = r.id
    JOIN public.permissions permission ON permission.permission_id = rp.permission_id
    JOIN public.institutions i ON i.institution_id = p_institution_id
    JOIN public.organizations o ON o.organization_id = i.organization_id
    WHERE u.id = p_actor_user_id AND u.status = 'active'
      AND r.name = 'admin' AND r.is_active
      AND ur.scope_type = 'institution' AND ur.scope_id = p_institution_id
      AND ur.scope_organization_id = i.organization_id
      AND i.is_active AND i.status = 'active' AND o.status = 'active'
      AND permission.is_active AND permission.scope = 'institution'
      AND permission.code IN (p_resource || '.manage', p_resource || '.*', '*')
    FOR SHARE OF u, ur, r, rp, permission, i, o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Institution administrator with academic permission required'
            USING ERRCODE = '42501';
    END IF;
END;
$$;

-- SOURCE validation.sql sha256=f3dd7e2af34d1a4bb02c6b50c47efcddee36a3dd5bb4473663037c008b6c23d3
-- Enforce ancestry and deactivation invariants even for privileged SQL writers.
CREATE FUNCTION public.validate_academic_foundation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    item jsonb := to_jsonb(NEW);
    previous jsonb;
    key text;
    parent_active boolean;
    check_parent boolean := TG_OP = 'INSERT';
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || NEW.institution_id::text, 0)
    );
    IF TG_OP = 'UPDATE' THEN
        previous := to_jsonb(OLD);
        FOR key IN SELECT jsonb_object_keys(item) LOOP
            IF (key LIKE '%\_id' ESCAPE '\' OR key = 'created_at')
               AND item -> key IS DISTINCT FROM previous -> key THEN
                RAISE EXCEPTION 'Academic identity and ancestry are immutable' USING ERRCODE = '22023';
            END IF;
        END LOOP;
        check_parent := NEW.is_active AND NOT OLD.is_active;
    END IF;
    IF check_parent AND NOT EXISTS (
        SELECT 1 FROM public.institutions i
        JOIN public.organizations o ON o.organization_id = i.organization_id
        WHERE i.institution_id = NEW.institution_id
          AND i.is_active AND i.status = 'active' AND o.status = 'active'
    ) THEN
        RAISE EXCEPTION 'Active institution and organization required' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME = 'programs' THEN
        SELECT d.is_active INTO parent_active FROM public.departments d
        WHERE d.department_id = NEW.department_id AND d.institution_id = NEW.institution_id
        FOR SHARE OF d;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Department not found in institution' USING ERRCODE = '23503';
        END IF;
        IF check_parent AND NOT parent_active THEN
            RAISE EXCEPTION 'Active department required' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'departments' AND NOT NEW.is_active THEN
        IF EXISTS (
            SELECT 1 FROM public.programs p
            WHERE p.department_id = NEW.department_id
              AND p.institution_id = NEW.institution_id AND p.is_active
        ) THEN
            RAISE EXCEPTION 'Deactivate dependent degree programs first' USING ERRCODE = '23514';
        END IF;
    END IF;
    NEW.name := btrim(NEW.name);
    NEW.code := btrim(NEW.code);
    IF TG_OP = 'INSERT' THEN NEW.created_at := now(); END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- SOURCE write.sql sha256=6dc9ee0b7777c8a727ca0f6be4f6db0bad9f878de6b3ee7490b9c1d14b62a661
CREATE FUNCTION public.manage_academic_foundation(
    p_actor_user_id uuid, p_institution_id uuid, p_entity text, p_record_id uuid, p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    id_column text;
    allowed text[];
    required text[] := ARRAY['name', 'code'];
    key text;
    kind text;
    before_row jsonb;
    after_row jsonb;
    effective jsonb;
    item_id uuid := COALESCE(p_record_id, gen_random_uuid());
    fields text;
    expressions text;
BEGIN
    CASE p_entity
    WHEN 'departments' THEN
        id_column := 'department_id';
        allowed := ARRAY['name', 'code', 'description', 'is_active'];
    WHEN 'programs' THEN
        id_column := 'program_id';
        allowed := ARRAY['department_id', 'name', 'code', 'description', 'degree_type',
                         'duration_years', 'total_credits', 'is_active'];
        required := required || ARRAY['department_id', 'degree_type', 'duration_years'];
    WHEN 'academic_years' THEN
        id_column := 'academic_year_id';
        allowed := ARRAY['name', 'code', 'start_date', 'end_date', 'is_current', 'is_active'];
        required := required || ARRAY['start_date', 'end_date'];
    ELSE RAISE EXCEPTION 'Unknown academic foundation entity' USING ERRCODE = '22023';
    END CASE;
    PERFORM public.assert_academic_foundation_actor(p_actor_user_id, p_institution_id, p_entity);
    IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' OR p_payload = '{}'::jsonb THEN
        RAISE EXCEPTION 'Academic fields required' USING ERRCODE = '22023';
    END IF;
    IF p_record_id IS NULL AND NOT p_payload ?& required THEN
        RAISE EXCEPTION 'Required academic fields missing' USING ERRCODE = '22023';
    END IF;
    FOR key IN SELECT jsonb_object_keys(p_payload) LOOP
        IF NOT key = ANY(allowed) OR (p_record_id IS NOT NULL AND key = 'department_id') THEN
            RAISE EXCEPTION 'Unsupported or immutable academic field' USING ERRCODE = '22023';
        END IF;
        kind := jsonb_typeof(p_payload -> key);
        IF kind = 'null' AND key NOT IN ('description', 'total_credits') THEN
            RAISE EXCEPTION 'Required academic field cannot be null' USING ERRCODE = '22023';
        END IF;
        IF kind <> 'null' AND (
            (key IN ('is_active', 'is_current') AND kind <> 'boolean') OR
            (key IN ('duration_years', 'total_credits') AND kind <> 'number') OR
            (key NOT IN ('is_active', 'is_current', 'duration_years', 'total_credits') AND kind <> 'string')
        ) THEN
            RAISE EXCEPTION 'Invalid academic field type' USING ERRCODE = '22023';
        END IF;
    END LOOP;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || p_institution_id::text, 0)
    );
    IF p_record_id IS NOT NULL THEN
        EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I = $1 AND institution_id = $2 FOR UPDATE',
                       p_entity, id_column) INTO before_row USING p_record_id, p_institution_id;
        IF before_row IS NULL THEN
            RAISE EXCEPTION 'Academic record not found' USING ERRCODE = 'P0002';
        END IF;
    END IF;
    effective := COALESCE(before_row, '{}'::jsonb) || p_payload ||
        jsonb_build_object(id_column, item_id, 'institution_id', p_institution_id);
    -- Whitelisted entity and field identifiers are quoted; values remain bound.
    -- Omitted create fields use table defaults instead of jsonb nulls.
    SELECT string_agg(format('%I', k), ','), string_agg(format('r.%I', k), ',')
    INTO fields, expressions
    FROM jsonb_object_keys(CASE WHEN p_record_id IS NULL THEN effective ELSE p_payload END) AS k;
    IF p_record_id IS NULL THEN
        EXECUTE format('INSERT INTO public.%I AS t (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) r RETURNING to_jsonb(t)',
                       p_entity, fields, expressions, p_entity) INTO after_row USING effective;
    ELSE
        EXECUTE format('UPDATE public.%I AS t SET (%s) = (SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) r) WHERE %I = $2 AND institution_id = $3 RETURNING to_jsonb(t)',
                       p_entity, fields, expressions, p_entity, id_column)
        INTO after_row USING effective, p_record_id, p_institution_id;
    END IF;
    INSERT INTO public.admin_audit_log (
        actor_user_id, institution_id, action, table_name, record_id, record_data, status
    ) VALUES (
        p_actor_user_id, p_institution_id,
        'academic.' || p_entity || CASE WHEN p_record_id IS NULL THEN '.create'
            WHEN before_row ->> 'is_active' = 'true' AND after_row ->> 'is_active' = 'false'
                THEN '.deactivate'
            WHEN before_row ->> 'is_active' = 'false' AND after_row ->> 'is_active' = 'true'
                THEN '.activate' ELSE '.update' END,
        p_entity, item_id::text, jsonb_build_object('before', before_row, 'after', after_row), 'success'
    );
    RETURN after_row;
END;
$$;

-- SOURCE security.sql sha256=9c4917f2a69e65055acf050100182c1ea129082f41fdfc72796ad9c5133e7ee0
DO $$
DECLARE entity text;
BEGIN
    FOREACH entity IN ARRAY ARRAY['departments', 'programs', 'academic_years'] LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres', entity);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', entity);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role', entity);
        -- Reads are tenant-filtered by the backend repository. All mutations
        -- require the actor-checked, audited SECURITY DEFINER entry point.
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role', entity);
        EXECUTE format('CREATE TRIGGER academic_foundation_validate BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.validate_academic_foundation()', entity);
    END LOOP;
END;
$$;
ALTER FUNCTION public.assert_academic_foundation_actor(uuid, uuid, text) OWNER TO postgres;
ALTER FUNCTION public.validate_academic_foundation() OWNER TO postgres;
ALTER FUNCTION public.manage_academic_foundation(uuid, uuid, text, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.assert_academic_foundation_actor(uuid, uuid, text),
    public.validate_academic_foundation(),
    public.manage_academic_foundation(uuid, uuid, text, uuid, jsonb)
    FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.manage_academic_foundation(uuid, uuid, text, uuid, jsonb) TO service_role;
NOTIFY pgrst, 'reload schema';
COMMIT;
